import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/data/users.db')
AUTH_MODE = os.environ.get('AUTH_MODE', 'legacy')
QUERY_LOG = os.environ.get('QUERY_LOG', 'false')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, password_hash TEXT, role TEXT, email TEXT)')
    db.execute("INSERT OR IGNORE INTO users (id, username, password_hash, role, email) VALUES (1, 'admin', 'e99a18c428cb38d5f260853678922e03', 'admin', 'admin@corp.local')")
    db.execute("INSERT OR IGNORE INTO users (id, username, password_hash, role, email) VALUES (2, 'user1', '5f4dcc3b5aa765d61d8327deb882cf99', 'viewer', 'user1@corp.local')")
    db.commit()
    db.close()

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above, value is user input
    query = f"SELECT id, username, role, email FROM users WHERE {field} LIKE '%{value}%'"

    if QUERY_LOG == 'true':
        app.logger.info(f"Executing query: {query}")

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v1/users/authenticate', methods=['POST'])
def authenticate():
    """Authenticate user credentials."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    if AUTH_MODE == 'legacy':
        # Legacy mode - direct DB lookup
        pw_hash = hashlib.md5(password.encode()).hexdigest()
        query = f"SELECT id, username, role FROM users WHERE username='{username}' AND password_hash='{pw_hash}'"
        try:
            db = get_db()
            cursor = db.execute(query)
            user = cursor.fetchone()
            if user:
                return jsonify({'authenticated': True, 'user': dict(user)})
            return jsonify({'authenticated': False}), 401
        except sqlite3.Error as e:
            return jsonify({'error': 'Auth error'}), 500
    else:
        # Modern mode - parameterized
        pw_hash = hashlib.md5(password.encode()).hexdigest()
        db = get_db()
        cursor = db.execute(
            "SELECT id, username, role FROM users WHERE username=? AND password_hash=?",
            (username, pw_hash)
        )
        user = cursor.fetchone()
        if user:
            return jsonify({'authenticated': True, 'user': dict(user)})
        return jsonify({'authenticated': False}), 401

@app.route('/api/v1/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    """Get user profile by ID."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, role, email FROM users WHERE id=?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'auth_mode': AUTH_MODE})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
